insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23677')::uuid, md5('building-alter-teichweg-15-21-22081')::uuid, '23677', 'moderne-bueroflaeche-mit-tollen-blick-auf-den-osterbekkanal-23677', 'Moderne Bürofläche mit tollen Blick auf den Osterbekkanal', 'Der moderne Neubau befindet sich in idyllischer Lage nahe dem Osterbekkanal in Barmbek. Der Barmbeker Bahnhof mit zahlreichen Anschlüssen an das Bus-, U- und S-Bahnnetz liegt nur …', 'Der moderne Neubau befindet sich in idyllischer Lage nahe dem Osterbekkanal in Barmbek. Der Barmbeker Bahnhof mit zahlreichen Anschlüssen an das Bus-, U- und S-Bahnnetz liegt nur wenige Gehminuten entfernt und sichert einen hervorragenden Anschluss an das öffentliche Verkehrsnetz.  Auch die Fuhlsbüttler Straße mit vielfältigen Einkaufsmöglichkeiten und zahlreichen gastronomischen Angeboten ist schnell erreicht. Die zur Untervermietung stehende Fläche wird über ein helles Foyer mit Personenaufzug erschlossen. Die vakante Einheit verfügt aktuell über Teppichfußboden, Stehleuchten, teilweise außen liegenden, elektrischen Sonnenschutz, Glasschwerter, Bodentanks bzw. Fensterbrüstungskanälen, einen Serverraum, separate WC-Einheiten auf dem Flur sowie eine kleine Pantry. PKW-Stellplätze können auf dem Hof oder in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], 247, 731, 'https://www.buerohamburg.de/objects/pdf/BHI_23677.pdf', null, 'filemaker', '23677') on conflict (id) do nothing;
