insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23546')::uuid, md5('building-caffamacherreihe-5-7-20355')::uuid, '23546', 'neustadt-hochwertiges-buero-im-brahms-quartier-mit-terrasse-23546', 'Neustadt: Hochwertiges Büro im Brahms Quartier mit Terrasse', 'Das moderne Büro- und Geschäftsgebäude befindet sich in erstklassiger City-Lage nur wenige Meter vom Gänsemarkt entfernt. Vielseitige Einkaufsmöglichkeiten und diverse Cafés und …', 'Das moderne Büro- und Geschäftsgebäude befindet sich in erstklassiger City-Lage nur wenige Meter vom Gänsemarkt entfernt. Vielseitige Einkaufsmöglichkeiten und diverse Cafés und Restaurants prägen das lebendige Umfeld. Die nahe gelegenen U- und S-Bahnstationen Gänsemarkt und Jungfernstieg sichern die Anbindung an das öffentliche Verkehrsnetz. Zur aktuellen Ausstattung der Bürofläche zählt ein hochwertiger Teppichbodenbelag, bodentiefe Fenster mit außenliegendem Sonnenschutz, Hohlraumboden, eine moderne Teeküche sowie getrennte WC-Einheiten. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Highlight ist eine Terrasse welche schon in der o.g. Gesamtfläche enthalten ist. Die Innenansichten stammen aus einer ähnlichen Fläche im Objekt. Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'erdgeschoss', 'stellplaetze']::text[], 413, 1045, 'https://www.buerohamburg.de/objects/pdf/BHI_23546.pdf', null, 'filemaker', '23546') on conflict (id) do nothing;
