  (md5('image-23546-1')::uuid, md5('property-23546')::uuid, 'https://www.buerohamburg.de/objects/images/23546/01_webBig.jpg', 'Neustadt: Hochwertiges Büro im Brahms Quartier mit Terrasse – Bild 1', 0, 'filemaker', '23546-01'),
