insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23250')::uuid, md5('building-ueberseeallee-10-20457')::uuid, '23250', 'attraktive-bueroflaeche-im-watermark-in-der-hafen-city-23250', 'Attraktive Bürofläche im WATERMARK in der Hafen-City', 'Der attraktive Neubau WATERMARK befindet sich im Herzen der Hafen City. Der Anschluss an das öffentliche Verkehrsnetz ist durch die nahegelegene U- Bahnstation Überseequartier …', 'Der attraktive Neubau WATERMARK befindet sich im Herzen der Hafen City. Der Anschluss an das öffentliche Verkehrsnetz ist durch die nahegelegene U- Bahnstation Überseequartier gewährleistet. Ein Supermarkt und diverse gastronomische Angebote im direkten Umfeld erhöhen die Attraktivität des Standortes. Die Bürofläche erschließt sich über einen modernen Eingangsbereich mit zwei Personenaufzügen und hat im 18. Obergeschoss eine 330 qm große Dachterrasse, die für alle Mieter im Haus zugänglich ist. Ein Highlight der hellen und attraktiven Bürofläche ist ein toller Ausblick über die Hafen City und die Elbe. Aktuell verfügt die Bürofläche über einen außenliegenden Sonnenschutz, Stehleuchten, Hohlraumboden für die Verkabelung, eine Kühlung über Betonaktivierung, sowie über eine Be- und Entlüftungsanlage. PKW-Stellplätze stehen in der hauseigenen Tiefgarage zur Anmietung bereit.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], 765, 2307, 'https://www.buerohamburg.de/objects/pdf/BHI_23250.pdf', null, 'filemaker', '23250') on conflict (id) do nothing;
