insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23821')::uuid, md5('building-frankenstrasse-18-20-20097')::uuid, '23821', 'arbeiten-in-repraesentativer-lage-am-wasser-23821', 'Arbeiten in repräsentativer Lage am Wasser', 'Direkt am Mittelkanal in der City-Süd befindet sich dieses repräsentative Bürogebäude, der „FrankenQuai“. Die Anbindung an den ÖPNV ist durch die nahegelegene S-Bahnstation …', 'Direkt am Mittelkanal in der City-Süd befindet sich dieses repräsentative Bürogebäude, der „FrankenQuai“. Die Anbindung an den ÖPNV ist durch die nahegelegene S-Bahnstation Hammerbrook gewährleistet und auch der Hauptbahnhof sowie die Innenstadt sind nur eine Station entfernt. Eine vielseitige Auswahl gastronomischer Betriebe sowie Geschäfte für kleinere Einkäufe sind fußläufig schnell erreicht. Das moderne Objekt ist mit hochwertigen Materialien ausgestattet und verfügt über einen außenliegenden elektrischen Sonnenschutz, einen Hohlraumboden mit Bodentanks, eine Betonkernaktivierung, eine Teeküche sowie getrennte WC-Einheiten. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Highlight sind mehrere Balkone, welche mit ca. 45 qm zur oben genannten Mietfläche addiert wird. PKW-Stellplätze können im hauseigenen Hof oder Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'stellplaetze']::text[], 407, 1214, 'https://www.buerohamburg.de/objects/pdf/BHI_23821.pdf', null, 'filemaker', '23821') on conflict (id) do nothing;
