insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-18294')::uuid, md5('building-am-sandtorkai-66-20457')::uuid, '18294', 'repraesentative-bueroflaeche-im-herzen-der-hafencity-18294', 'Repräsentative Bürofläche im Herzen der HafenCity', 'Das moderne Bürogebäude liegt in prominenter HafenCity-Lage. Die Anbindung an das öffentliche Verkehrsnetz ist durch die fußläufig schnell erreichte U-Bahnstation Baumwall und den …', 'Das moderne Bürogebäude liegt in prominenter HafenCity-Lage. Die Anbindung an das öffentliche Verkehrsnetz ist durch die fußläufig schnell erreichte U-Bahnstation Baumwall und den fünfminütig verkehrenden Metrobus 6 von und zum Hauptbahnhof gesichert. Im lebendigen Umfeld befinden sich diverse Cafés und Restaurants. Auch die Hamburger Innenstadt mit allen Einkaufsmöglichkeiten und einem abwechslungsreichen gastronomischen Angebot ist nur wenige Gehminuten entfernt. Die helle und moderne Mietfläche erstreckt sich über zwei Ebenen, welche mit einer internen Treppe verbunden sind. Die hochwertige Ausstattung umfasst u.a. einen offenen Empfangsbereich, Parkettboden, teilweise Teppichfußboden, EDV-Verkabelung, einen klimatisierten Serverraum, mehrere Pantries, Glastrennwände und separate WC-Einheiten. Highlight der Fläche ist der direkte Blick auf die Speicherstadt und die Elbphilharmonie. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze', 'wasserblick']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_18294.pdf', null, 'filemaker', '18294') on conflict (id) do nothing;
