insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22804')::uuid, md5('building-haferweg-36-46-22761')::uuid, '22804', 'moderne-bueroflaeche-im-businesspark-eimsbuettel-22804', 'Moderne Bürofläche im Businesspark Eimsbüttel', 'Das gepflegte Bürogebäude befindet sich in verkehrsgünstiger Lage nahe der Kieler Straße. Der S-Bahnhof Diebsteich und diverse Buslinien sichern eine gute Anbindung an den ÖPNV. …', 'Das gepflegte Bürogebäude befindet sich in verkehrsgünstiger Lage nahe der Kieler Straße. Der S-Bahnhof Diebsteich und diverse Buslinien sichern eine gute Anbindung an den ÖPNV. Auch der Anschluss an die A7 ist in wenigen Fahrminuten erreicht. Die moderne Bürofläche erschließt sich über ein helles Foyer mit Personenaufzug.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-22804-1')::uuid, md5('property-22804')::uuid, 'Mietfläche', 818, 12.9, null, 'filemaker', '22804-1') on conflict (id) do nothing;
