insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-16430')::uuid, md5('building-notkestrasse-13-15-22607')::uuid, '16430', 'ansprechender-buerokomplex-sunny-point-in-bahrenfeld-16430', 'Ansprechender Bürokomplex Sunny Point in Bahrenfeld', 'Der gepflegte Bürokomplex Sunny Point befindet sich in zentraler Lage des Hamburger Stadtteils Bahrenfeld. Der Altonaer Volkspark, die Trabrennbahn und das Elbe Einkaufszentrum …', 'Der gepflegte Bürokomplex Sunny Point befindet sich in zentraler Lage des Hamburger Stadtteils Bahrenfeld. Der Altonaer Volkspark, die Trabrennbahn und das Elbe Einkaufszentrum mit zahlreichen Einkaufsmöglichkeiten und gastronomischen Angeboten sind fußläufig schnell erreicht. Eine Buslinie sichert den direkten Anschluss an den ÖPNV. Das Objekt wird barrierefrei über einen repräsentativen Eingangsbereich mit drei Personen- und Lastenaufzügen erschlossen. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-16430-1')::uuid, md5('property-16430')::uuid, 'Mietfläche', 819, 13, null, 'filemaker', '16430-1') on conflict (id) do nothing;
