insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-1039')::uuid, md5('building-raboisen-38-40-20095')::uuid, '1039', 'altstadt-moderne-bueroflaeche-in-der-hamburger-city-1039', 'Altstadt: Moderne Bürofläche in der Hamburger City', 'Das markante Bürogebäude befindet sich nahe der Alster in bester Innenstadtlage. Der Hauptbahnhof mit allen Anschlüssen an das U- und S-Bahnnetz und Fernverbindungen ist in …', 'Das markante Bürogebäude befindet sich nahe der Alster in bester Innenstadtlage. Der Hauptbahnhof mit allen Anschlüssen an das U- und S-Bahnnetz und Fernverbindungen ist in wenigen Gehminuten erreicht. Vielseitige Einkaufsmöglichkeiten und ein abwechslungsreiches gastronomisches Angebot in diversen Cafés und Restaurants prägen das direkte Umfeld. Das moderne Büro erschließt sich über ein repräsentatives Foyer mit gläsernem Personenaufzug. Die aktuelle Ausstattung umfasst Teppich- und Amticofußboden in Holzoptik, Akustikdecken, Stehleuchten, einen klimatisierten Serverraum, separate WC-Einheiten und eine moderne Pantry. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 250, 825, 'https://www.buerohamburg.de/objects/pdf/BHI_1039.pdf', null, 'filemaker', '1039') on conflict (id) do nothing;
