insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25322')::uuid, md5('building-neuer-wall-10-20354')::uuid, '25322', 'buero-in-bester-adresslage-direkt-an-der-alster-25322', 'Büro in bester Adresslage direkt an der Alster', 'Nur wenige Meter von der Binnenalster und dem Rathausmarkt entfernt befindet sich dieses imposante Kontorhaus in einer der gefragtesten Geschäftslagen Hamburgs. Der U- und …', 'Nur wenige Meter von der Binnenalster und dem Rathausmarkt entfernt befindet sich dieses imposante Kontorhaus in einer der gefragtesten Geschäftslagen Hamburgs. Der U- und S-Bahnhof Jungfernstieg ist fußläufig ebenfalls schnell erreicht. Das Büro- und Geschäftgebäude verfügt über einen eindrucksvollen Eingangsbereich sowie Personenaufzüge. Die großzügige Bürofläche direkt an der Binnenalster und kann nach Absprache nach den individuellen Wünschen des neuen Mieters aufgeteilt und ausgestattet werden. Diese Innenbilder sind beispielhaft gewählt. PKW-Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], 318, 831, 'https://www.buerohamburg.de/objects/pdf/BHI_25322.pdf', null, 'filemaker', '25322') on conflict (id) do nothing;
