insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25364')::uuid, md5('building-waterloohain-9-22769')::uuid, '25364', 'moderne-architektur-im-kreativen-umfeld-25364', 'Moderne Architektur im kreativen Umfeld', 'Das architektonisch außergewöhnliche Bürogebäude befindet sich in verkehrsgünstiger Lage zur A7 mit einer guten Anbindung an den ÖPNV. Neben der S-Bahnhaltestelle Holstenstraße, …', 'Das architektonisch außergewöhnliche Bürogebäude befindet sich in verkehrsgünstiger Lage zur A7 mit einer guten Anbindung an den ÖPNV. Neben der S-Bahnhaltestelle Holstenstraße, liegen auch die U-Bahnhaltestellen Emilienstraße und Christuskirche sowie diverse Bushaltestellen in fußläufiger Entfernung. Der Standort ist durch eine Vielzahl an Medienunternehmen und Agenturen kreativ geprägt. Eine vielseitige Auswahl an Restaurants und Cafés beleben das direkte Umfeld. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25364-1')::uuid, md5('property-25364')::uuid, 'Mietfläche', 850, 16.9, null, 'filemaker', '25364-1') on conflict (id) do nothing;
