insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22516')::uuid, md5('building-spaldingstrasse-64-68-20097')::uuid, '22516', 'moderne-bueroflaeche-in-markanter-city-lage-22516', 'Moderne Bürofläche in markanter City-Lage', 'Das Spaldingtor überzeugt durch einmalige Architektur in markanter Lage zwischen Spalding- und Nordkanalstraße. Die oberen, vorgelagerten Stockwerke werden durch prägnante …', 'Das Spaldingtor überzeugt durch einmalige Architektur in markanter Lage zwischen Spalding- und Nordkanalstraße. Die oberen, vorgelagerten Stockwerke werden durch prägnante Säulenformationen gestützt und bestimmen den unverwechselbaren Charakter dieser Immobilie. Im Umfeld befinden sich diverse gastronomische Angebote und auch der nahe gelegene Hauptbahnhof sorgt für ein gutes Mittagsangebot sowie eine hervorragende Anbindung an das öffentliche Verkehrsnetz.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-22516-1')::uuid, md5('property-22516')::uuid, 'Mietfläche', 854, 13, null, 'filemaker', '22516-1') on conflict (id) do nothing;
