insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23658')::uuid, md5('building-hans-henny-jahnn-weg-29-33-22085')::uuid, '23658', 'uhlenhorst-charmante-bueroflaeche-mit-terrasse-am-osterbekkanal-23658', 'Uhlenhorst: Charmante Bürofläche mit Terrasse am Osterbekkanal', 'Das repräsentative Bürohaus befindet sich im beliebten Stadtteil Uhlenhorst unmittelbar am schönen Osterbekkanal. Die Anbindung an den ÖPNV ist durch die Buslinien gegeben. Diese …', 'Das repräsentative Bürohaus befindet sich im beliebten Stadtteil Uhlenhorst unmittelbar am schönen Osterbekkanal. Die Anbindung an den ÖPNV ist durch die Buslinien gegeben. Diese sind ebenso wie diverse Geschäfte des täglichen Bedarfs und Restaurants im Mühlenkamp fußläufig schnell zu erreichen. Die Bürofläche verteilt sich auf zwei Ebenen welche mit einer internen Treppe verbunden sind. Zur Ausstattung zählt u.a. außenliegender Sonnenschutz, Designboden in den Verkehrs- und Showroomflächen, Teppichboden in den Büros, Bodentanks sowie getrennte WC-Einheiten. Eine Terrasse am Kanal schließt sich direkt an die Fläche an. Diese Fläche erstreckt sich vom Fleetgeschoss bis ins 1.Obergeschoss. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können nach Rücksprache in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'erdgeschoss', 'stellplaetze', 'wasserblick']::text[], 344, 1602, 'https://www.buerohamburg.de/objects/pdf/BHI_23658.pdf', null, 'filemaker', '23658') on conflict (id) do nothing;
