insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25268')::uuid, md5('building-heidenkampsweg-81-20097')::uuid, '25268', 'hochwertige-bueroflaeche-mit-herrlichem-fleetblick-25268', 'Hochwertige Bürofläche mit herrlichem Fleetblick', 'Das PIER81 befindet sich direkt am Wasser in einer markanten Ecklage in der CitySüd. Die Autobahnen A1, A7 und A24 sowie die Innenstadt sind in wenigen Fahrminuten erreicht. Die …', 'Das PIER81 befindet sich direkt am Wasser in einer markanten Ecklage in der CitySüd. Die Autobahnen A1, A7 und A24 sowie die Innenstadt sind in wenigen Fahrminuten erreicht. Die Anbindung an den ÖPNV ist durch die nahegelegene S-Bahnstation Hammerbrook sowie diverse Buslinien und eine Haltestelle direkt vor dem Haus gesichert. Das Umfeld ist geprägt durch zahlreiche gastronomische Angebote und Wochenmärkte. Eine hauseigene Kantine mit großer Terrasse am Wasser rundet das Versorgungsangebot ab.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25268-1')::uuid, md5('property-25268')::uuid, 'Mietfläche', 855, 16, null, 'filemaker', '25268-1') on conflict (id) do nothing;
