insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-7306')::uuid, md5('building-hammerbrookstrasse-94-20097')::uuid, '7306', 'individuell-gestaltbare-bueroflaeche-im-herzen-der-city-sued-7306', 'Individuell gestaltbare Bürofläche im Herzen der City-Süd', 'Das im Jahr 2005 fertiggestellte Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage in der City Süd, zwischen den Elbbrücken und der Hamburger Innenstadt, …', 'Das im Jahr 2005 fertiggestellte Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage in der City Süd, zwischen den Elbbrücken und der Hamburger Innenstadt, unmittelbar an der S-Bahn-Station Hammerbrook. Im direkten Umfeld stehen zahlreiche Cafés und Restaurants zur Verfügung, die bequem fußläufig erreichbar sind.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-7306-1')::uuid, md5('property-7306')::uuid, 'Mietfläche', 858, 14.5, null, 'filemaker', '7306-1') on conflict (id) do nothing;
