insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-20366')::uuid, md5('building-nagelsweg-55-20097')::uuid, '20366', 'city-sued-moderne-bueroflaeche-im-hansa-carr-e-20366', 'City-Süd: Moderne Bürofläche im Hansa-Carrée', 'Das Hansa-Carree befindet sich in zentraler Lage in der City-Süd. Die ÖPNV-Anbindung ist durch die fußläufig schnell erreichte S-Bahnstation Hammerbrook gesichert. Auch die …', 'Das Hansa-Carree befindet sich in zentraler Lage in der City-Süd. Die ÖPNV-Anbindung ist durch die fußläufig schnell erreichte S-Bahnstation Hammerbrook gesichert. Auch die Elbbrücken mit Anbindung an die A1 und A7 sind nur wenige Fahrminuten entfernt. Das moderne Gebäude besticht durch eine ansprechende Fassade aus Rotklinker und Glas und ist mit Personen- und Lastenaufzügen und einer eigenen Kantine ausgestattet. Die Bürofläche  verfügt sowohl über Sonnenschutzverglasung als auch über außenliegenden Sonnenschutz und wird in Absprache mit dem zukünftigen Mieter aufgeteilt. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Die Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 135, 858, 'https://www.buerohamburg.de/objects/pdf/BHI_20366.pdf', null, 'filemaker', '20366') on conflict (id) do nothing;
