insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-10345')::uuid, md5('building-museumstrasse-39-22765')::uuid, '10345', 'modernes-buero-hinter-historischer-fassade-10345', 'Modernes Büro hinter historischer Fassade', 'Das markante Rotklinkergebäude befindet sich bester Lage von Ottensen. Der Altonaer Bahnhof, mit zahlreichen Bus- und Bahnverbindungen sowie Anschluss an den Fernverkehr, liegt …', 'Das markante Rotklinkergebäude befindet sich bester Lage von Ottensen. Der Altonaer Bahnhof, mit zahlreichen Bus- und Bahnverbindungen sowie Anschluss an den Fernverkehr, liegt nur wenige Meter entfernt. Alle Geschäfte des täglichen Bedarfs sowie zahlreiche Restaurants und Cafés befinden sich im direkten Umfeld. Durch die offen gestaltete, überdachte Eingangshalle gelangt man zu den Aufzugsanlagen. Die Bürofläche verfügt über Beleuchtungssysteme, Teppichfußboden, eine moderne Pantry sowie getrennte WC-Einheiten. Die Aufteilung sowie die weitere Ausstattung erfolgen in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze stehen im hauseigenen Parkhaus zur Anmietung bereit.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 224, 863, 'https://www.buerohamburg.de/objects/pdf/BHI_10345.pdf', null, 'filemaker', '10345') on conflict (id) do nothing;
insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-10345-1')::uuid, md5('property-10345')::uuid, 'Mietfläche', 863, 19, null, 'filemaker', '10345-1') on conflict (id) do nothing;
