insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-6278')::uuid, md5('building-mexikoring-27-33-22297')::uuid, '6278', 'bueroflaeche-mit-einzigartigem-ausblick-6278', 'Bürofläche mit einzigartigem Ausblick', 'Die City-Nord gehört zu den bekanntesten und wichtigsten Bürostandorten Hamburgs. Nicht nur die sehr gute Anbindung an den öffentlichen Nahverkehr und den Flughafen, sondern auch …', 'Die City-Nord gehört zu den bekanntesten und wichtigsten Bürostandorten Hamburgs. Nicht nur die sehr gute Anbindung an den öffentlichen Nahverkehr und den Flughafen, sondern auch die unmittelbare Nähe zum Stadtpark machen diese Lage so attraktiv. Die helle Bürofläche wird über einen Personenaufzug erschlossen und ist unter anderem mit Teppichboden, außenliegender Sonnenschutz, Deckenbeleuchtung, getrennten WC-Einheiten und einer Teeküche ausgestattet. Weitere Ausbau- und Ausstattungswünsche erfolgen in Rücksprache mit dem zukünftigen Mieter. Der Mietpreis variiert je nach Ausbauwunsch des Mieters zzgl. Nebenkosten und Mehrwertsteuer. Die Innenansichten sind beispielhaft gewählt. PKW-Stellplätze und Lagerflächen können vor Ort angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['lastenaufzug', 'stellplaetze']::text[], 130, 1175, 'https://www.buerohamburg.de/objects/pdf/BHI_6278.pdf', null, 'filemaker', '6278') on conflict (id) do nothing;
