insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24738')::uuid, md5('building-barmbeker-strasse-2-12-22303')::uuid, '24738', 'kampnagel-moderne-bueroflaeche-mit-fleetblick-24738', 'Kampnagel - moderne Bürofläche mit Fleetblick', 'Das Medien- und Kulturzentrum Kampnagel befindet sich in belebter Lage von Winterhude in unmittelbarer Nähe zum Osterbekkanal. Das Umfeld ist geprägt durch Geschäfte des täglichen …', 'Das Medien- und Kulturzentrum Kampnagel befindet sich in belebter Lage von Winterhude in unmittelbarer Nähe zum Osterbekkanal. Das Umfeld ist geprägt durch Geschäfte des täglichen Bedarfs sowie zahlreiche Cafés und Restaurants. Die U-Bahnstation Borgweg sowie diverse Bushaltestellen sind nach wenigen Minuten erreicht. Die Bürofläche wird über einen Personenaufzug barrierefrei erschlossen. Zur aktuellen Ausstattung zählen bodentiefe Fenster, Teppich- und Linoleumfußboden, Beleuchtungssysteme, Bodentanks, teilweise außen liegender elektrischer Sonnenschutz, getrennte WC-Einheiten und eine Pantry. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Die Innenansichten stammen aus einer ähnlichen Fläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 266, 893, 'https://www.buerohamburg.de/objects/pdf/BHI_24738.pdf', null, 'filemaker', '24738') on conflict (id) do nothing;
